        answer = [answer] * len(completions)
    elif isinstance(answer, list) and len(answer) == 1 and len(completions) > 1:
        answer = answer * len(completions)
    if isinstance(prompts, str):
        prompts = [prompts] * len(completions)
    elif isinstance(prompts, list) and len(prompts) == 1 and len(completions) > 1:
        prompts = prompts * len(completions)
    def _clamp(x):
        if x < -2.0:
            return -2.0
        if x > 5.0:
            return 5.0
        return float(x)
    def _prompt_text(p):
        if isinstance(p, str):
            return p
        try:
            for msg in reversed(p):
                if isinstance(msg, dict) and msg.get('role') == 'user':
                    return msg.get('content', '')
            for msg in p:
                if isinstance(msg, dict) and 'content' in msg:
                    return msg.get('content', '')
        except Exception:
            pass
        return ''
    scores = []
    for prompt, completion, true_answer in zip(prompts, completions, answer):
        try:
            if isinstance(completion, dict):
                text = completion.get('content', '')
            else:
                text = completion[0]['content']
        except Exception:
            text = ''
        sol = None
        try:
            sol = extract_solution(text)
        except Exception:
            sol = None
        if sol is None:
            m = re.search('<solution>(.*?)</solution>', text, re.DOTALL)
            if m is not None:
                sol = m.group(1)
        sol = sol.strip() if isinstance(sol, str) else ''
        try:
            correct = is_correct(sol, true_answer)
        except Exception:
            correct = False
        ptext = _prompt_text(prompt).lower()
        requested = False
        match = False
        if 'ordered pair' in ptext:
            requested = True
            match = ('(' in sol and ')' in sol and ',' in sol)
        elif 'interval notation' in ptext:
            requested = True
            match = any(c in sol for c in '()[]')
        elif 'common fraction' in ptext:
            requested = True
            match = ('frac' in sol or '/' in sol)
        elif 'degrees' in ptext:
            requested = True
            match = ('circ' in sol or 'degree' in sol)
        elif 'trigonometric function' in ptext:
            requested = True
            match = any(fn in sol for fn in ['sin', 'cos', 'tan', 'csc', 'sec', 'cot'])
        elif 'simplest radical' in ptext:
            requested = True
            match = ('sqrt' in sol)
        if correct:
            score = 5.0 if (not requested or match) else 4.5
        else:
            score = -1.0
            if requested:
                score += 1.5 if match else -0.5
        scores.append(_clamp(score))
    return scores

