            if s[i] == '(':
                depth = 1
                j = i + 1
                while j < len(s) and depth > 0:
                    if s[j] == '(':
                        depth += 1
                    elif s[j] == ')':
                        depth -= 1
                    j += 1
                if depth == 0:
                    inner = s[i + 1:j - 1]
                    if ',' in inner:
                        parts = inner.split(',', 1)
                        coords.append((parts[0].strip(), parts[1].strip()))
                i = j
            else:
                i += 1
        return coords
